public class Main {
    static char grade(int marks) {
        if (marks >= 90) {
            return 'A';
        } else if (marks >= 75) {
            return 'B';
        } else if (marks >= 60) {
            return 'C';
        } else if (marks >= 40) {
            return 'D';
        }
        return 'F';
    }

    public static void main(String[] args) {
        int[] marks = {90, 89, 75, 60, 40, 39};
        for (int m : marks) {
            System.out.println(m + " " + grade(m));
        }
    }
}
